/// <summary>
/// Custom helper class for frequently used functions
/// </summary>
class METHelper
{
}

Method.Source:
    /// <summary>
    /// Gets dimension value
    /// </summary>
    /// <param name = "_defaultDimension">RecId of default dimension</param>
    /// <param name = "_dimensionName">Dimension name</param>
    /// <returns>Returns dimension value</returns>
    public static DimensionValue getDimensionValue(RecId _defaultDimension, Name _dimensionName)
    {
        DimensionAttributeValueSetStorage dimStorage;
        ;

        dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);

        return dimStorage.getDisplayValueByDimensionAttribute(DimensionAttribute::findByName(_dimensionName).RecId);
    }

    /// <summary>
    /// Merge a LedgerDimension that has a main account only with DefaultDimensions
    /// </summary>
    /// <param name = "_defaultDimension">RecId of default dimension</param>
    /// <param name = "_ledgerDimensionId">RecId of the ledger dimension</param>
    /// <returns>Returns merged dimension value</returns>
    public static LedgerDimensionBase createLedgerDimFromLedgerDefaultDimensions(DimensionDefault _defaultDimension, LedgerDimensionBase _ledgerDimensionId)
    {
        //use this method for merging a LedgerDimension that has a main account only with DefaultDimensions to get a new LedgerDimension that has main account + dimensions
        LedgerDimensionBase LedgerDimensionIdAC, mergedLedgerDimension;

        //create a LedgerDimensionId that has Account Structure attached.
        LedgerDimensionIdAC = LedgerDimensionFacade::serviceCreateLedgerDimension(_ledgerDimensionId);

        //create new LedgerDimension from existing LedgerDimension plus Default dimensions
        mergedLedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimForDefaultDim(_defaultDimension, LedgerDimensionIdAC);

        return mergedLedgerDimension;
    }

    /// <summary>
    /// Returns word
    /// </summary>
    /// <param name = "_num">Number</param>
    /// <returns>String</returns>
    public static str getWord(str _num)
    {
        str ret;

        switch(_num)
        {
            case "1": ret = "@SYS26620"; break;
            case "2": ret = "@SYS26621"; break;
            case "3": ret = "@SYS26622"; break;
            case "4": ret = "@SYS26626"; break;
            case "5": ret = "@SYS26627"; break;
            case "6": ret = "@SYS26628"; break;
            case "7": ret = "@SYS26629"; break;
            case "8": ret = "@SYS26630"; break;
            case "9": ret = "@SYS26631"; break;
            default: ret = "@SYS2068"; break;

        }
        return ret;
    }
